/*master.mpif.selectMasterMpifErrList*/
SELECT Z.BUYER_ID, Z.COM_CODE, Z.IF_TYPE, Z.ERR_CNT, SUBSTR(Z.EX_TERM,2,10)||DECODE(SUBSTR(Z.EX_TERM,1,1),'D','일','H','시간','M','분') AS EX_TERM, Z.IF_DIRECTION, Z.PROGRAM_ID, Z.IF_STATUS_IMG, Z.IF_STATUS, TO_CHAR(Z.LAST_UPDATE_DATE,'YYYY/MM/DD HH24:MI:SS') AS LAST_UPDATE_DATE, Z.TASK_GUBUN, Z.TASK_ORDER, Z.PROCESS_GUBUN, Z.CHECKING_IMG, Z.CHECKING FROM ( SELECT A.BUYER_ID, A.COM_CODE, A.IF_TYPE, A.ERR_CNT, A.EX_TERM, A.IF_DIRECTION, A.PROGRAM_ID, CASE WHEN A.IF_STATUS = 'ON' AND A.LAST_UPDATE_DATE >= SYSDATE-(DECODE(SUBSTR(EX_TERM,1,1),'D',1,'H',1/24,'M',1/60/24))*SUBSTR(EX_TERM,2,10) THEN '0' ELSE '2' END AS IF_STATUS_IMG, CASE WHEN A.IF_STATUS = 'ON' AND LAST_UPDATE_DATE >= SYSDATE-(DECODE(SUBSTR(EX_TERM,1,1),'D',1,'H',1/24,'M',1/60/24))*SUBSTR(EX_TERM,2,10) THEN 'ON' ELSE 'OFF' END AS IF_STATUS, A.LAST_UPDATE_DATE, A.TASK_GUBUN, A.TASK_ORDER, A.PROCESS_GUBUN, CASE WHEN (SELECT COUNT(1) FROM ICOMTRXL WHERE DOC_NAME = 'IF_CHECK' AND TARGET = A.BUYER_ID AND KEY_1 = A.IF_TYPE AND KEY_2 = A.TASK_GUBUN AND KEY_9 = ' ') > 0 THEN '1' WHEN (SELECT COUNT(1) FROM ICOMTRXL WHERE DOC_NAME = 'IF_CHECK' AND TARGET = 'ALL' AND KEY_9 = ' ') > 0 THEN '1' ELSE '0' END AS CHECKING_IMG, CASE WHEN (SELECT COUNT(1) FROM ICOMTRXL WHERE DOC_NAME = 'IF_CHECK' AND TARGET = A.BUYER_ID AND KEY_1 = A.IF_TYPE AND KEY_2 = A.TASK_GUBUN AND KEY_9 = ' ') > 0 THEN '1' WHEN (SELECT COUNT(1) FROM ICOMTRXL WHERE DOC_NAME = 'IF_CHECK' AND TARGET = 'ALL' AND KEY_9 = ' ') > 0 THEN '1' ELSE '0' END AS CHECKING FROM EAI.IF_ERR_MNG A WHERE 1 = 1
AND A.BUYER_ID IN (SELECT DISTINCT BUYER_ID FROM IF_ADMIN WHERE BUYER IN
#{item}
)
AND A.BUYER_ID = UPPER(#{st_buyer_id})
AND A.ERR_CNT > 0
AND A.ERR_CNT = 0
) Z WHERE 1 = 1
AND Z.IF_STATUS = #{st_if_status_flag}
ORDER BY Z.COM_CODE, Z.IF_TYPE

/*master.mpif.selectMasterMpifErrList*/
SELECT A.PGM_ID, A.PGM_NAME, B.SEQ, B.CREATE_DATE, B.CREATE_TIME, CASE WHEN B.ERR_TYPE = 'A' THEN '0' /* 작업대기 */ WHEN B.ERR_TYPE = 'B' THEN '1' /* 정상 */ WHEN B.ERR_TYPE = 'C' THEN '2' /* I/F오류 */ END ERR_TYPEIMG /* 상태 Image */, CASE WHEN B.ERR_TYPE = 'A' THEN '장애' /* 작업대기 */ WHEN B.ERR_TYPE = 'B' THEN '데이터 이슈' /* 정상 */ WHEN B.ERR_TYPE = 'C' THEN 'I/F오류' /* I/F오류 */ END ERR_TYPE , B.ERR_TITLE, B.ERR_NOTE, A.JOB_NOTE, CASE WHEN B.STATUS = 'E' THEN '오류' /* 오류 */ WHEN B.STATUS = 'R' THEN '접수' /* 접수 */ WHEN B.STATUS = 'C' THEN '완료' /* 완료 */ END STATUS /* 상태값 */, CASE WHEN B.STATUS = 'E' THEN '0' /* 오류 */ WHEN B.STATUS = 'R' THEN '2' /* 접수 */ WHEN B.STATUS = 'C' THEN '3' /* 완료 */ END STATUSIMG /* 상태 Image */, B.RECEIPT_USER_ID, B.RECEIPT_DATE, B.COMPLETE_USER_ID, B.COMPLETE_DATE FROM IF_PGM_HD A , IF_PGM_DT B WHERE A.PGM_ID = B.PGM_ID
AND B.CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.PGM_ID LIKE '%' || #{st_pgm_id} || '%'
AND B.ERR_TYPE = #{st_error_flag}
AND B.STATUS = #{st_if_status_flag}

