/*updateReceiptMpifNewErrMngPop*/

		UPDATE IF_PGM_DT
		SET RECEIPT_USER_ID = #{st_user_id}
		  , STATUS = 'R'
		  , RECEIPT_DATE = SYSDATE
		WHERE 1=1
		AND SEQ = #{err_seq}

/*updateCompleteMpifNewErrMngPop*/

		UPDATE IF_PGM_DT
		SET COMPLETE_USER_ID = #{st_user_id}
		  , STATUS = 'C'
		  , COMPLETE_DATE = SYSDATE
		WHERE 1=1
		AND SEQ = #{err_seq}

/*updateCompleteMpifNewErrMngPop*/

		UPDATE IF_PGM_HD
		SET JOB_NOTE    = #{st_df_remark}
		WHERE 1=1
		AND PGM_ID = #{PGM_ID}
